import * as THREE from 'three';
const materials={};
for(const role of ['start','finish']){const c=document.createElement('canvas');c.width=512;c.height=144;const x=c.getContext('2d');x.fillStyle=role==='start'?'#315b49':'#9c563f';x.beginPath();x.roundRect(4,4,504,136,25);x.fill();x.strokeStyle='#fff7e5';x.lineWidth=5;x.lineCap='round';if(role==='start'){x.beginPath();x.moveTo(42,94);x.lineTo(42,42);x.lineTo(82,67);x.closePath();x.stroke();}else{x.strokeRect(39,36,49,39);x.beginPath();x.moveTo(39,36);x.lineTo(39,105);x.stroke();x.fillStyle='#fff7e5';for(let i=0;i<3;i++)for(let j=0;j<2;j++)if((i+j)%2===0)x.fillRect(40+i*16,37+j*19,16,19);}x.fillStyle='#fff7e5';x.font='600 49px sans-serif';x.textBaseline='middle';x.fillText(role.toUpperCase(),111,75);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;materials[role]=new THREE.MeshBasicMaterial({map:t,transparent:true,depthWrite:false,side:THREE.DoubleSide});}
const geometry=new THREE.PlaneGeometry(.43,.121);
export function syncRouteMarker(hold){let tag=hold.getObjectByName('routeMarker');const role=hold.userData.role;if(!['start','finish'].includes(role)){if(tag)hold.remove(tag);return;}if(!tag){tag=new THREE.Mesh(geometry,materials[role]);tag.name='routeMarker';hold.add(tag);}tag.material=materials[role];const scale=hold.userData.size,rot=hold.rotation.z;hold.geometry.computeBoundingBox();const b=hold.geometry.boundingBox;let bottom=Infinity;for(const x of [b.min.x,b.max.x])for(const y of [b.min.y,b.max.y])bottom=Math.min(bottom,(x*Math.sin(rot)+y*Math.cos(rot))*scale);const offset=bottom-.105;tag.position.set(Math.sin(rot)*offset/scale,Math.cos(rot)*offset/scale,.005/scale);tag.rotation.z=-rot;tag.scale.setScalar(1/scale);}
